  src_counts: "{d} heute · {n} gesamt", all_src: "alle Quellen: {n}", all_sources: "Alle Quellen", src_col: "Quelle / Gerät", src_gone: "Quelle entfernt", input_dev: "Eingang: {d}",
  no_ffmpeg: "ffmpeg fehlt im Add-on – Stream-Quellen funktionieren nicht.",
  tls_missing: "Der HTTPS-Server für Handys läuft nicht ({e}).",
  port_missing: "Der Handy-Port ist abgeschaltet. Einstellungen → Add-ons → GLighter → Netzwerk: bei „8443/tcp“ einen freien Port eintragen (Standard 18443), speichern, Add-on neu starten.",
  src_help: "Handy (Browser): QR-Code scannen, Seite in Chrome öffnen, Start tippen. Der Bildschirm muss an bleiben (Ladegerät).\nHandy-App / Stream-URL: z. B. Android-App „IP Webcam“ – darin „Server starten“ und hier http://HANDY-IP:8080/audio.wav eintragen. Läuft auch mit ausgeschaltetem Bildschirm.\nJede Quelle lernt ihren Hintergrund getrennt. Über „⚙ Pegel & Schwelle“ bekommt jedes Gerät auf Wunsch eigene Einstellungen; mit „Verstärkung“ gleichst du leise Handys an.",
  copy: "Kopieren", new_link: "Neuen Link erzeugen", mdns_hint: "Tipp: Viele Android-Handys kennen „.local“-Namen nicht. Öffne das Panel einmal über die IP-Adresse (z. B. http://192.168.178.43:8123), dann steht hier die IP.",
  qr_steps: "Handy ins gleiche WLAN wie Home Assistant.|QR-Code mit der Kamera scannen und den Link in Chrome öffnen.|Warnung „Verbindung ist nicht privat“: auf „Erweitert“ → „Weiter zu … (unsicher)“. Das ist normal, das Add-on nutzt ein eigenes Zertifikat.|Auf „Start“ tippen und das Mikrofon erlauben.|Handy ans Ladegerät und dorthin legen, wo der Lärm herkommt. Seite offen lassen.",
