  dt_add: "Zeile hinzufügen", dt_up: "nach oben", dt_down: "nach unten", dt_rm: "Zeile entfernen", dt_view: "Darstellung", dt_none_row: "keine Tagesaufzeichnung für dieses Gerät im Zeitraum",
