  st_need_pro: "Selbst einstellen geht nur mit Pro.", st_limit: "Höchstens 40 Kacheln.", st_del_q: "Kachel „{n}“ löschen? Die Daten bleiben unverändert.",
  rec_only: "Nur aufzeichnen (keine Erkennung)", rec_only_b: "nur Aufzeichnung", h_rec_only: "Der Pegel wird weiter in der Tagesaufzeichnung gespeichert (mit Prüfsumme, live und im Verlauf sichtbar). Aus diesem Gerät entstehen aber keine Störungen, keine KI-Einordnung, keine Lärmspur und keine Meldung an Home Assistant.", ntg_own: "Eigene", qt_add: "Eigene", qt_create: "Anlegen", qt_add_tip: "Eigene Schnellwahl-Taste anlegen oder Tasten verwalten", qt_tip: "Klick: wählen · Rechtsklick oder lange drücken: verwalten",
  qt_title: "Schnellwahl verwalten", qt_new_ph: "Neue Taste, z. B. Waschmaschine", qt_sug: "„{w}“ schon {n}× getippt – als Taste anlegen?", qt_sug_no: "Nicht mehr vorschlagen",
  qt_sug_h: "Oft getippt – als Taste anlegen?", qt_learn_h: "GLighter merkt sich Wörter, die du oft selbst tippst, und schlägt sie hier als Taste vor (nie von selbst).",
