  fb_wait_cnt: "Press ＋1 – every press is saved with the exact time",
  fb_ed_sure: "Sure?", fc_lay_gnew: "New group", fb_il_drag: "Move “{l}”: drag or arrow keys", fb_il_more: "More settings for “{l}”",
